BEGIN
 SELECT relowner INTO STRICT owner_id FROM pg_class WHERE oid='public.memories'::regclass;
 IF owner_id<>(SELECT oid FROM pg_roles WHERE rolname=current_user) THEN
  RAISE EXCEPTION 'private_transcript_preparation_owner_changed';END IF;
 -- Authenticate catalog bodies and complete metadata before any guard can run.
 FOR expected IN SELECT value FROM jsonb_array_elements('[{"signature":"application_native_root_cover(uuid,jsonb)","language":"plpgsql","body":"f8967430fbfc755009756e8b3deaba790d8d218d82e06bbd9b57ac394e14607c","metadata":{"probin":null,"procost":100,"prokind":"f","proname":"application_native_root_cover","prorows":0,"pronargs":2,"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["w","roots"],"proargtypes":["2950","3802"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"prepare_native_session_message_covered(uuid,uuid,text,jsonb,jsonb)","language":"plpgsql","body":"6b67c90a35970c0ff6e289088998c225f7a3e284bc5628b115fe4c23a1993ae4","metadata":{"probin":null,"procost":100,"prokind":"f","proname":"prepare_native_session_message_covered","prorows":0,"pronargs":5,"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["w","s","producer","sources","target"],"proargtypes":["2950","2950","25","3802","3802"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"read_native_covered_session_frame(uuid,text[],uuid[],text[])","language":"plpgsql","body":"7529bbac0ee75d5cb12bc091f079b40d99c767979e5384cad58c5c6b59a84816","metadata":{"probin":null,"procost":100,"prokind":"f","proname":"read_native_covered_session_frame","prorows":0,"pronargs":4,"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["w","kinds","ids","versions"],"proargtypes":["2950","1009","2951","1009"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"native_turn_helpers_current()","language":"sql","volatility":"s","bodyTemplate":"803d9cd34a7c94347e32172c77ea7387d5cb8e642f905ca08f7f18b796451255","metadata":{"probin":null,"procost":100,"prokind":"f","proname":"native_turn_helpers_current","prorows":0,"pronargs":0,"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"16","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"s","proleakproof":false,"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"native_retained_helpers_current()","language":"sql","body":"964833b5d2ef9fa4b273631fa1a8eecbfc7d1b6a0b1fa84744aa87688e22c895","metadata":{"probin":null,"procost":100,"prokind":"f","proname":"native_retained_helpers_current","prorows":0,"pronargs":0,"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"16","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"s","proleakproof":false,"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}}]'::jsonb) LOOP
  SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.'||(expected->>'signature'));
  IF actual.oid IS NULL OR actual.proowner IS DISTINCT FROM owner_id OR actual.pronamespace<>'public'::regnamespace
   OR actual.prolang IS DISTINCT FROM (SELECT oid FROM pg_language WHERE lanname=expected->>'language')
   OR (to_jsonb(actual)-ARRAY['oid','prosrc','proowner','pronamespace','prolang','proacl']) IS DISTINCT FROM expected->'metadata'
   OR EXISTS(SELECT 1 FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))) a
    WHERE a.grantee<>owner_id OR a.grantor<>owner_id OR a.privilege_type<>'EXECUTE' OR a.is_grantable)
  THEN RAISE EXCEPTION 'private_transcript_preparation_predecessor_changed: %',expected->>'signature';END IF;
  IF expected->>'signature'='native_turn_helpers_current()' THEN
   IF cardinality(turn_members)<>149 OR (SELECT count(DISTINCT member) FROM unnest(turn_members) member)<>149 THEN
    RAISE EXCEPTION 'private_transcript_preparation_native_roster_changed';END IF;
   SELECT 'ARRAY['||string_agg(quote_literal(member),',' ORDER BY member)||']::text[]' INTO declared_roster FROM unnest(turn_members) member;
   IF (length(actual.prosrc)-length(replace(actual.prosrc,declared_roster,'')))/length(declared_roster)<>1
    OR encode(sha256(convert_to(replace(actual.prosrc,declared_roster,'__ROSTER__'),'UTF8')),'hex') IS DISTINCT FROM expected->>'bodyTemplate'
   THEN RAISE EXCEPTION 'private_transcript_preparation_predecessor_changed: %',expected->>'signature';END IF;
  ELSIF encode(sha256(convert_to(actual.prosrc,'UTF8')),'hex') IS DISTINCT FROM expected->>'body' THEN
   RAISE EXCEPTION 'private_transcript_preparation_predecessor_changed: %',expected->>'signature';
  END IF;
 END LOOP;
 -- These tables are immutable executable manifests, not authority-result caches.
 -- Read their exact declared rosters only after validating non-executable table
 -- shape, owner and ACL. No catalog-defined guard is invoked by this migration.
 FOREACH signature IN ARRAY ARRAY['native_turn_contract_helpers','native_retained_contract_helpers'] LOOP
  SELECT * INTO relation FROM pg_class WHERE oid=to_regclass('public.'||signature);
  IF relation.oid IS NULL OR relation.relowner<>owner_id OR relation.relnamespace<>'public'::regnamespace
   OR relation.relkind<>'r' OR relation.relpersistence<>'p' OR NOT relation.relrowsecurity OR relation.relforcerowsecurity
   OR relation.relispartition OR EXISTS(SELECT 1 FROM pg_inherits WHERE inhrelid=relation.oid OR inhparent=relation.oid)
   OR EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=relation.oid)
   OR EXISTS(SELECT 1 FROM aclexplode(coalesce(relation.relacl,acldefault('r',relation.relowner))) a
    WHERE a.grantee<>owner_id OR a.grantor<>owner_id OR a.is_grantable)
   OR (SELECT array_agg(attname::text ORDER BY attnum) FROM pg_attribute WHERE attrelid=relation.oid AND attnum>0 AND NOT attisdropped) IS DISTINCT FROM ARRAY['signature','fingerprint']
   OR EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=relation.oid AND attnum>0 AND NOT attisdropped
    AND (atttypid<>'text'::regtype OR NOT attnotnull OR attidentity<>'' OR attgenerated<>'' OR attacl IS NOT NULL))
  THEN RAISE EXCEPTION 'private_transcript_preparation_registry_changed: %',signature;END IF;
  expected_members:=CASE WHEN signature='native_turn_contract_helpers' THEN turn_members ELSE retained_members END;
  SELECT array_agg(member ORDER BY member) INTO expected_members FROM unnest(expected_members) member;
  EXECUTE format('SELECT array_agg(signature ORDER BY signature),jsonb_agg(to_jsonb(h) ORDER BY signature) FROM public.%I h',signature) INTO members,registry_rows;
  IF members IS DISTINCT FROM expected_members THEN
   RAISE EXCEPTION 'private_transcript_preparation_registry_changed: %',signature;END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(registry_rows) h LEFT JOIN pg_proc p ON p.oid=to_regprocedure('public.'||(h->>'signature'))
   WHERE p.oid IS NULL OR p.proowner<>owner_id OR p.pronamespace<>'public'::regnamespace
    OR h->>'fingerprint' IS DISTINCT FROM encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex')) THEN
   RAISE EXCEPTION 'private_transcript_preparation_registry_changed: %',signature;END IF;
  SELECT jsonb_build_object('class',to_jsonb(relation),
   'columns',(SELECT jsonb_agg(to_jsonb(a) ORDER BY attnum) FROM pg_attribute a WHERE attrelid=relation.oid),
   'constraints',(SELECT jsonb_agg(to_jsonb(c) ORDER BY oid) FROM pg_constraint c WHERE conrelid=relation.oid),
   'indexes',(SELECT jsonb_agg(to_jsonb(i) ORDER BY indexrelid) FROM pg_index i WHERE indrelid=relation.oid),
   'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY oid) FROM pg_policy p WHERE polrelid=relation.oid),
   'triggers',(SELECT jsonb_agg(to_jsonb(t) ORDER BY oid) FROM pg_trigger t WHERE tgrelid=relation.oid),
   'rules',(SELECT jsonb_agg(to_jsonb(r) ORDER BY oid) FROM pg_rewrite r WHERE ev_class=relation.oid)) INTO catalog;
  INSERT INTO pg_temp.private_transcript_preparation_registries VALUES(signature,catalog,registry_rows);
 END LOOP;
 -- Authenticate the current closed nested comparator, without executing it.
 -- Its reviewed 8267 successor compares complete pg_proc rows for exactly
 -- these 201 members. Only target-local catalog/OID/ACL literals vary; the
 -- complete executable prefix, column comparator and suffix remain exact.
