 -- Discover immutable obligations before D1 can drop their native carrier.$eligibility_branch$);
 EXECUTE replace(pg_get_functiondef('prepare_native_session_message_covered(uuid,uuid,text,jsonb,jsonb)'::regprocedure),original,successor);
 UPDATE pg_temp.private_transcript_preparation_originals SET expected_body=successor WHERE signature='prepare_native_session_message_covered(uuid,uuid,text,jsonb,jsonb)';
END $eligibility$;
DO $controlled_repin$
<<controlled_repin>>
DECLARE previous record;caller record;body text;round integer;changed boolean;
BEGIN
 FOR round IN 1..64 LOOP
  RAISE NOTICE 'Private transcript: authenticated pin round %',round;
  changed:=false;
  IF EXISTS(SELECT 1 FROM pg_temp.private_transcript_preparation_originals o LEFT JOIN pg_proc p ON p.oid=o.oid
   WHERE p.oid IS NULL OR p.prosrc IS DISTINCT FROM o.expected_body OR (to_jsonb(p)-'prosrc') IS DISTINCT FROM o.metadata)
  THEN RAISE EXCEPTION 'private_transcript_preparation_authenticated_code_changed';END IF;
  FOR previous IN SELECT o.*,p.prosrc current_body,
   encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex') current_fingerprint,
   encode(sha256(convert_to(p.prosrc,'UTF8')),'hex') current_hash
   FROM pg_temp.private_transcript_preparation_originals o JOIN pg_proc p ON p.oid=o.oid WHERE o.body IS DISTINCT FROM p.prosrc
  LOOP
   FOR caller IN SELECT p.oid,p.prosrc FROM pg_proc p WHERE p.oid<>previous.oid AND
    (position(previous.quoted_body IN p.prosrc)>0 OR position(previous.fingerprint IN p.prosrc)>0 OR position(previous.body_hash IN p.prosrc)>0)
   LOOP
    IF NOT EXISTS(SELECT 1 FROM pg_temp.private_transcript_preparation_originals o WHERE o.oid=caller.oid AND o.expected_body=caller.prosrc)
    THEN RAISE EXCEPTION 'private_transcript_preparation_unauthenticated_pin_consumer: %',caller.oid::regprocedure;END IF;
    body:=replace(replace(replace(caller.prosrc,previous.quoted_body,quote_literal(previous.current_body)),previous.fingerprint,previous.current_fingerprint),previous.body_hash,previous.current_hash);
    IF body IS DISTINCT FROM caller.prosrc THEN
     EXECUTE replace(pg_get_functiondef(caller.oid),caller.prosrc,body);
     UPDATE pg_temp.private_transcript_preparation_originals SET expected_body=controlled_repin.body WHERE oid=caller.oid;
     changed:=true;
    END IF;
   END LOOP;
   UPDATE pg_temp.private_transcript_preparation_originals SET body=previous.current_body,quoted_body=quote_literal(previous.current_body),
    fingerprint=previous.current_fingerprint,body_hash=previous.current_hash WHERE oid=previous.oid;
  END LOOP;
  IF NOT changed THEN EXIT;END IF;
  IF round=64 THEN RAISE EXCEPTION 'private_transcript_preparation_pin_cycle';END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM pg_temp.private_transcript_preparation_originals o LEFT JOIN pg_proc p ON p.oid=o.oid
  WHERE p.oid IS NULL OR p.prosrc IS DISTINCT FROM o.expected_body OR (to_jsonb(p)-'prosrc') IS DISTINCT FROM o.metadata)
 THEN RAISE EXCEPTION 'private_transcript_preparation_successor_code_changed';END IF;
END $controlled_repin$;
-- None of the three reviewed successors belongs to either flat registry.
-- Prove their complete rows and catalog contracts remain unchanged; do not
-- rewrite registry entries to bless unrelated runtime drift.
DO $successor$
DECLARE saved record;relation pg_class;catalog jsonb;registry_rows jsonb;
BEGIN
 FOR saved IN SELECT * FROM pg_temp.private_transcript_preparation_registries LOOP
  SELECT * INTO relation FROM pg_class WHERE oid=to_regclass('public.'||saved.name);
  SELECT jsonb_build_object('class',to_jsonb(relation),
   'columns',(SELECT jsonb_agg(to_jsonb(a) ORDER BY attnum) FROM pg_attribute a WHERE attrelid=relation.oid),
   'constraints',(SELECT jsonb_agg(to_jsonb(c) ORDER BY oid) FROM pg_constraint c WHERE conrelid=relation.oid),
   'indexes',(SELECT jsonb_agg(to_jsonb(i) ORDER BY indexrelid) FROM pg_index i WHERE indrelid=relation.oid),
   'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY oid) FROM pg_policy p WHERE polrelid=relation.oid),
   'triggers',(SELECT jsonb_agg(to_jsonb(t) ORDER BY oid) FROM pg_trigger t WHERE tgrelid=relation.oid),
   'rules',(SELECT jsonb_agg(to_jsonb(r) ORDER BY oid) FROM pg_rewrite r WHERE ev_class=relation.oid)) INTO catalog;
  EXECUTE format('SELECT jsonb_agg(to_jsonb(h) ORDER BY signature) FROM public.%I h',saved.name) INTO registry_rows;
  IF catalog IS DISTINCT FROM saved.catalog OR registry_rows IS DISTINCT FROM saved.rows
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(registry_rows) h LEFT JOIN pg_proc p ON p.oid=to_regprocedure('public.'||(h->>'signature'))
    WHERE p.oid IS NULL OR h->>'fingerprint' IS DISTINCT FROM encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex')) THEN
   RAISE EXCEPTION 'private_transcript_preparation_successor_contract_changed: %',saved.name;END IF;
 END LOOP;
END $successor$;
COMMIT;
